<script setup lang="ts">
import {ref,computed} from 'vue'
const ratio=ref(.75),show=ref(false);const patches=Array.from({length:64},(_,i)=>({i,x:i%8,y:Math.floor(i/8),rank:(i*37+11)%64}));const hidden=computed(()=>Math.round(ratio.value*64))
const col=(p:any)=>p.y>5?'#64748b':p.x>2&&p.x<6&&p.y>2?'#CF1C24':'#86d9f3'
</script>
<template><div class="demo"><div class="controls"><label>Taux masqué : {{Math.round(ratio*100)}} % <input aria-label="Taux de masquage" type="range" min=".125" max=".875" step=".125" v-model.number="ratio"></label><button @click="show=!show">{{show?'Cacher':'Montrer'}} les cibles</button><button @click="ratio=.75;show=false">Réinitialiser</button></div><div class="body"><svg viewBox="0 0 320 300"><g v-for="p in patches" :key="p.i"><rect :x="p.x*34+12" :y="p.y*34+10" width="31" height="31" :fill="p.rank<hidden&&!show?'#cbd5e1':col(p)" :stroke="p.rank<hidden?'#333':'transparent'"/><text v-if="p.rank<hidden&&!show" :x="p.x*34+28" :y="p.y*34+32" text-anchor="middle" style="font-size:16px">?</text></g></svg><div><h3>{{64-hidden}} tokens visibles pour l’encodeur</h3><p>{{hidden}} positions masquées à reconstruire.</p><p>Le décodeur reçoit les codes visibles, les positions et les tokens de masque.</p><p>Les couleurs révélées représentent les cibles de reconstruction du jeu synthétique.</p></div></div></div></template>
<style scoped>.demo{font:17px sans-serif}.controls{display:flex;gap:16px;align-items:center}.body{display:grid;grid-template-columns:340px 1fr;gap:28px}svg{height:300px}button{background:#eee;padding:6px;border-radius:5px}input{accent-color:#CF1C24}h3{color:#CF1C24}</style>
